-- The enum migration is complete; this Lua successor verifies the checked-in
-- generated catalog deterministically instead of depending on Python to rewrite it.
local path=require('tools.lua.lib.path');local root=path.repo_root();local output=path.join(root,'scripts','script-abi','src','stat_keys.rs');assert(path.is_file(output),'generated stat_keys.rs missing');local source=path.read(output);local normalized=source:gsub('=>%s*{%s*"','=> "');local seen={};local count=0;for variant,wire in normalized:gmatch('StatKey::([%w_]+)%s*=>%s*"([a-z0-9_]+)"')do assert(not seen[variant],'duplicate StatKey variant: '..variant);seen[variant]=wire;count=count+1 end;assert(count>0,'no generated StatKey variants found');local all=source:match('pub const ALL.-=%s*&%[(.-)%];');assert(all,'StatKey ALL array missing');local all_count=0;for variant in all:gmatch('StatKey::([%w_]+)')do assert(seen[variant],'ALL references unknown variant '..variant);all_count=all_count+1 end;assert(all_count==count,string.format('ALL contains %d variants but wire catalog contains %d',all_count,count));print(string.format('Verified %d generated StatKey variants (checked-in output unchanged)',count))
